static constexpr size_t kIndirectCallTableCount = 6340u;

RecompFuncPtr lookup_recompiled_function(uint32_t vaddr) {
    static constexpr uint32_t kLutBase  = 0x80003000u;
    static constexpr uint32_t kLutEnd   = 0x80308000u;
    static constexpr size_t   kLutSlots = (kLutEnd - kLutBase) >> 2;
    static RecompFuncPtr s_lut[kLutSlots]{};
    static std::once_flag s_init_once;
    std::call_once(s_init_once, []() {
        for (size_t i = 0; i < kIndirectCallTableCount; ++i) {
            const uint32_t va = kIndirectCallTable[i].vaddr;
            if (va >= kLutBase && va < kLutEnd && (va & 3u) == 0u) {
                s_lut[(va - kLutBase) >> 2] = kIndirectCallTable[i].fn;
            }
        }
    });
    if (vaddr >= kLutBase && vaddr < kLutEnd && (vaddr & 3u) == 0u) {
        return s_lut[(vaddr - kLutBase) >> 2];
    }
    auto it = std::lower_bound(
        kIndirectCallTable,
        kIndirectCallTable + kIndirectCallTableCount,
        vaddr,
        [](const IndirectCallEntry& e, uint32_t target) { return e.vaddr < target; }
    );
    if (it != (kIndirectCallTable + kIndirectCallTableCount) && it->vaddr == vaddr) {
        return it->fn;
    }
    return nullptr;
}

